if (!global.uvSum) global.uvSum = 0;
if (!global.uvCount) global.uvCount = 0;
if (!global.uvAverage) global.uvAverage = 0;

global.uv_tick = function() {
    try {
        var currentUV = Hub.getAccessory(537).getService(25).getCharacteristic(27).value;

        if (currentUV === null || isNaN(currentUV)) {
            log.warn("⚠️ УФ индекс недоступен, пропускаем.");
            return;
        }

        global.uvSum += currentUV;
        global.uvCount += 1;

    } catch (e) {
        log.error("⛔ Ошибка uv_tick: " + e.message);
    }
};

global.uv_calc = function() {
    try {
        if (global.uvCount === 0) {
            log.warn("⚠️ Нет данных УФ за период.");
            return;
        }

        global.uvAverage = Math.round(global.uvSum / global.uvCount);

        log.info("✅ УФ среднее за период: " + global.uvAverage + " (из " + global.uvCount + " значений)");

        Hub.getAccessory(537).getService(78).getCharacteristic(80).setValue(global.uvAverage);

        global.uvSum = 0;
        global.uvCount = 0;

    } catch (e) {
        log.error("⛔ Ошибка uv_calc: " + e.message);
    }
};
